INSERT INTO `menu` (`id_menu`, `nama_menu`, `kategori`, `harga`, `deskripsi`, `instruksi_masak`, `gambar_url`, `status_menu`) VALUES
(1, 'Beef Burger Classic', 'Makanan', 32000.00, 'Burger daging sapi panggang dengan selada, tomat, dan saus spesial', 'Panggang patty 4 menit per sisi. Panggang roti sebentar. Susun selada, tomat, patty, lalu saus.', NULL, 'aktif'),
(2, 'Cheese Burger Deluxe', 'Makanan', 38000.00, 'Burger sapi dengan dua lapis keju cheddar leleh', 'Panggang patty, letakkan keju di atas patty panas agar meleleh, lalu susun dalam roti.', NULL, 'aktif'),
(3, 'Chicken Burger Crispy', 'Makanan', 35000.00, 'Burger ayam crispy dengan mayones dan selada segar', 'Balur fillet dengan tepung bumbu, goreng 6 menit sampai keemasan, tiriskan, lalu susun.', NULL, 'aktif'),
(4, 'Fried Chicken 2 Pcs', 'Makanan', 28000.00, 'Dua potong ayam goreng tepung renyah', 'Marinasi ayam 30 menit, balur tepung bumbu, goreng dalam minyak panas 12 menit.', NULL, 'aktif'),
(5, 'Chicken Wings BBQ 6 Pcs', 'Makanan', 34000.00, 'Enam sayap ayam goreng dengan saus BBQ', 'Goreng sayap sampai matang, tiriskan, lalu aduk rata dengan saus BBQ selagi panas.', NULL, 'aktif'),
(6, 'Hot Dog Jumbo', 'Makanan', 26000.00, 'Sosis sapi jumbo dengan bawang bombay dan saus', 'Panggang sosis 5 menit, tumis bawang bombay, susun dalam roti hot dog, beri saus.', NULL, 'aktif'),
(7, 'Chicken Katsu Rice Bowl', 'Makanan', 30000.00, 'Nasi dengan ayam katsu dan saus manis gurih', 'Balur fillet dengan telur dan tepung panir, goreng, potong, sajikan di atas nasi.', NULL, 'aktif'),
(8, 'French Fries Original', 'Cemilan', 18000.00, 'Kentang goreng renyah dengan saus tomat', 'Goreng kentang beku 4 menit dalam minyak panas, tiriskan, taburi garam.', NULL, 'aktif'),
(9, 'Mozzarella Sticks', 'Cemilan', 24000.00, 'Stik keju mozzarella goreng yang meleleh', 'Balur keju dengan telur dan tepung panir, bekukan 15 menit, lalu goreng cepat.', NULL, 'aktif'),
(10, 'Onion Rings', 'Cemilan', 20000.00, 'Cincin bawang bombay goreng tepung', 'Potong bawang bombay melingkar, balur tepung bumbu, goreng sampai keemasan.', NULL, 'aktif'),
(11, 'Coca Cola Float', 'Minuman', 15000.00, 'Cola dingin dengan satu skop es krim vanila', 'Tuang cola ke gelas berisi es, tambahkan satu skop es krim vanila di atasnya.', NULL, 'aktif'),
(12, 'Iced Lemon Tea', 'Minuman', 12000.00, 'Teh lemon dingin yang menyegarkan', 'Seduh teh, dinginkan, tambahkan sirup lemon dan gula, sajikan dengan es batu.', NULL, 'aktif'),
(13, 'Chocolate Milkshake', 'Minuman', 22000.00, 'Milkshake coklat dengan es krim vanila', 'Blender susu, sirup coklat, dan es krim sampai halus dan berbusa.', NULL, 'aktif'),
(14, 'Iced Americano', 'Minuman', 16000.00, 'Espresso dingin dengan air dan es batu', 'Ekstraksi espresso dua shot, tuang ke gelas berisi air dingin dan es batu.', NULL, 'aktif'),
(15, 'Paket Hemat Combo', 'Paket', 55000.00, 'Burger sapi, kentang goreng, dan cola dalam satu paket', 'Siapkan burger sapi keju, kentang goreng porsi sedang, dan satu gelas cola dingin.', NULL, 'aktif');
